<?php
require_once __DIR__.'/../controllers/helpers.php';require_once __DIR__.'/../config/database.php';$user=requireRole(['etudiant']);$q=database()->prepare('SELECT sp.titre,sp.type,sp.fichier,sp.dateAjout,m.idModule,m.libelle FROM support sp JOIN module m ON m.idModule=sp.idModule JOIN semestre sm ON sm.idSemestre=m.idSemestre JOIN niveau n ON n.idNiveau=sm.idNiveau JOIN inscription i ON i.idNiveau=n.idNiveau JOIN dossier_etudiant d ON d.idDossier=i.idDossier WHERE d.idEtudiant=:id AND i.statut="VALIDEE" ORDER BY sp.dateAjout DESC');$q->execute(['id'=>$user['id']]);$rows=$q->fetchAll();$pageTitle='Supports de cours';$showSidebar=true;require __DIR__.'/../includes/header.php';?><h2>Supports de cours</h2><div class="card"><table><tr><th>Titre</th><th>Module</th><th>Type</th><th>Ajouté le</th><th></th></tr><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['titre'])?></td><td><?=htmlspecialchars('Module '.$row['idModule'].' - '.$row['libelle'])?></td><td><?=htmlspecialchars($row['type'])?></td><td><?=htmlspecialchars($row['dateAjout'])?></td><td><a href="<?=htmlspecialchars($row['fichier'])?>" target="_blank" rel="noopener">Ouvrir</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Aucun support disponible.</td></tr><?php endif;?></table></div><?php require __DIR__.'/../includes/footer.php';?>